(() => {
  const out = {};
  out.dpr = window.devicePixelRatio;
  out.htmlFontSize = getComputedStyle(document.documentElement).fontSize;
  out.bodyFontSize = getComputedStyle(document.body).fontSize;
  out.innerWidth = window.innerWidth;
  const h1 = document.querySelector('header h1');
  if (h1) out.h1 = { text: h1.textContent, fs: getComputedStyle(h1).fontSize, fw: getComputedStyle(h1).fontWeight, ff: getComputedStyle(h1).fontFamily };
  const nav = document.querySelector('nav[aria-label] span');
  if (nav) out.navLabel = { text: nav.textContent, fs: getComputedStyle(nav).fontSize };
  return out;
})()

(() => {
  window.__snap = (rootSel) => {
    const root = document.querySelector(rootSel);
    if (!root) return 'NOT FOUND ' + rootSel;
    const lines = [];
    const walk = (el, depth) => {
      if (depth > 14) return;
      const cs = getComputedStyle(el);
      if (cs.display === 'none') return;
      const own = Array.from(el.childNodes).filter(n => n.nodeType === 3 && n.textContent.trim()).map(n => n.textContent.trim()).join(' ');
      const r = el.getBoundingClientRect();
      const tag = el.tagName.toLowerCase();
      if (own || ['svg','img','input'].includes(tag)) {
        lines.push(`${'  '.repeat(depth)}${tag} "${own.slice(0,42)}" fs=${cs.fontSize} fw=${cs.fontWeight} c=${cs.color} h=${Math.round(r.height)}`);
      } else if (el.children.length && (cs.borderTopWidth !== '0px' || cs.backgroundColor !== 'rgba(0, 0, 0, 0)' || cs.borderRadius !== '0px')) {
        lines.push(`${'  '.repeat(depth)}${tag}[box] bg=${cs.backgroundColor} bd=${cs.borderTopWidth} ${cs.borderTopColor} r=${cs.borderRadius} p=${cs.padding} gap=${cs.gap} h=${Math.round(r.height)}`);
      }
      for (const c of el.children) walk(c, depth + 1);
    };
    walk(root, 0);
    return lines.join('\n');
  };
  return window.__snap('[role="dialog"], [data-slot="sheet-content"], [data-vaul-drawer]');
})()

(() => {
  const d = document.createElement('div');
  d.className = 'bg-primary-50 text-primary-700 border-primary-200 text-primary-800';
  document.body.appendChild(d);
  const cs = getComputedStyle(d);
  const r = { bg: cs.backgroundColor, color: cs.color, border: cs.borderColor };
  d.remove();
  const probe = (cls) => { const e = document.createElement('div'); e.className = cls; document.body.appendChild(e); const c = getComputedStyle(e).backgroundColor; e.remove(); return c; };
  return { combined: r, p50: probe('bg-primary-50'), p100: probe('bg-primary-100'), p200: probe('bg-primary-200'), p700: probe('bg-primary-700'), gray50: probe('bg-gray-50'), gray100: probe('bg-gray-100') };
})()

