// Merge the per-agent i18n drops into public/locale/en.json, alphabetically.
const fs = require("fs");
const path = require("path");

const SCRATCH = __dirname;
const EN = "/Users/bodhishthomas/code/care_fe/public/locale/en.json";

const en = JSON.parse(fs.readFileSync(EN, "utf8"));
const added = {};
const collisions = [];

for (const file of fs.readdirSync(SCRATCH)) {
  if (!/^i18n-.*\.json$/.test(file)) continue;
  const drop = JSON.parse(fs.readFileSync(path.join(SCRATCH, file), "utf8"));
  for (const [k, v] of Object.entries(drop)) {
    if (typeof v !== "string") continue;
    if (k in en) {
      if (en[k] !== v) collisions.push(`${file}: ${k} (existing "${en[k]}" kept, drop wanted "${v}")`);
      continue;
    }
    if (k in added && added[k] !== v) collisions.push(`${file}: ${k} conflicts with an earlier drop`);
    added[k] = v;
  }
}

const merged = { ...en, ...added };
const out = {};
for (const k of Object.keys(merged).sort()) out[k] = merged[k];
fs.writeFileSync(EN, JSON.stringify(out, null, 2) + "\n");

console.log(`added ${Object.keys(added).length} keys`);
for (const k of Object.keys(added).sort()) console.log(`  + ${k} = ${JSON.stringify(added[k])}`);
if (collisions.length) {
  console.log("\ncollisions (not written):");
  for (const c of collisions) console.log(`  ! ${c}`);
}

