60	/**
61	 * History arrives newest-first, so a run of consecutive rows sharing a year is
62	 * exactly the group the design labels.
63	 */
64	function groupVisitsByYear(history: PublicAppointment[]) {
65	  return history.reduce<{ year: string; visits: PublicAppointment[] }[]>(
66	    (groups, appointment) => {
67	      const year = dayjs(appointment.token_slot.start_datetime).format("YYYY");
68	      const current = groups.at(-1);
69	      if (current?.year === year) {
70	        current.visits.push(appointment);
71	      } else {
72	        groups.push({ year, visits: [appointment] });
73	      }
74	      return groups;
75	    },
76	    [],
77	  );
78	}
