1	import { useQuery } from "@tanstack/react-query";
2	import dayjs from "dayjs";
3	import { useMemo } from "react";
4	
5	import { usePatientContext } from "@/hooks/usePatientUser";
6	
7	import query from "@/Utils/request/query";
8	import { DiagnosticReportStatus } from "@/types/emr/diagnosticReport/diagnosticReport";
9	import patientPortalApi from "@/types/emr/patientPortal/patientPortalApi";
10	import { PrescriptionStatus } from "@/types/emr/prescription/prescription";
11	import PublicAppointmentApi from "@/types/scheduling/PublicAppointmentApi";
12	import {
13	  AppointmentFinalStatuses,
14	  PublicAppointment,
15	} from "@/types/scheduling/schedule";
16	
17	/**
18	 * The OTP portal endpoints return records for every patient linked to the
19	 * signed-in number, so every list must be narrowed to the active profile.
20	 *
21	 * Prescriptions and diagnostic reports are scoped server-side via the `patient`
22	 * query param — their list payloads carry no patient reference, so filtering
23	 * client-side is not possible. Appointments carry a `patient` and are filtered
24	 * locally.
25	 *
26	 * The selected patient id is part of every query key: without it React Query
27	 * serves one patient's cached records to another after a switch.
28	 */
29	function useAuthHeaders() {
30	  const { tokenData } = usePatientContext();
31	  return {
32	    token: tokenData?.token,
33	    phoneNumber: tokenData?.phoneNumber,
34	    headers: { Authorization: `Bearer ${tokenData?.token}` },
35	  };
36	}
37	
38	export function usePatientAppointments() {
39	  const { selectedPatient } = usePatientContext();
40	  const { token, phoneNumber, headers } = useAuthHeaders();
41	
42	  const { data, isLoading } = useQuery({
43	    queryKey: ["appointment", phoneNumber, selectedPatient?.id],
44	    queryFn: query(PublicAppointmentApi.getAppointments, { headers }),
45	    enabled: !!token,
46	  });
47	
48	  return useMemo(() => {
49	    const appointments = (data?.results ?? [])
50	      .filter((appointment) => appointment.patient.id === selectedPatient?.id)
51	      .sort(
52	        (a, b) =>
53	          new Date(a.token_slot.start_datetime).getTime() -
54	          new Date(b.token_slot.start_datetime).getTime(),
55	      );
56	
57	    const isUpcoming = (appointment: PublicAppointment) =>
58	      dayjs(appointment.token_slot.start_datetime).isAfter(dayjs()) &&
59	      !AppointmentFinalStatuses.includes(appointment.status);
60	
61	    const upcoming = appointments.filter(isUpcoming);
62	
63	    return {
64	      isLoading,
65	      appointments,
66	      upcoming,
67	      // Most recent first — history reads backwards from today.
68	      history: appointments.filter((a) => !isUpcoming(a)).reverse(),
69	      nextAppointment: upcoming[0],
70	    };
71	  }, [data, isLoading, selectedPatient?.id]);
72	}
73	
74	export function usePatientPrescriptions() {
75	  const { selectedPatient } = usePatientContext();
76	  const { token, phoneNumber, headers } = useAuthHeaders();
77	
78	  const { data, isLoading } = useQuery({
79	    queryKey: ["portal-prescriptions", phoneNumber, selectedPatient?.id],
80	    // Silent: deployments whose backend predates the portal prescription
81	    // endpoint would otherwise toast "Not Found" on every screen that shows a
82	    // prescription summary. The empty state covers it.
83	    queryFn: query(patientPortalApi.listPrescriptions, {
84	      headers,
85	      queryParams: { patient: selectedPatient?.id },
86	      silent: true,
87	    }),
88	    enabled: !!token && !!selectedPatient?.id,
89	  });
90	
91	  return useMemo(() => {
92	    const prescriptions = (data?.results ?? [])
93	      .slice()
94	      .sort(
95	        (a, b) =>
96	          new Date(b.created_date).getTime() -
97	          new Date(a.created_date).getTime(),
98	      );
99	
100	    return {
101	      isLoading,
102	      prescriptions,
103	      active: prescriptions.filter(
104	        (p) => p.status === PrescriptionStatus.active,
105	      ),
106	      past: prescriptions.filter((p) => p.status !== PrescriptionStatus.active),
107	    };
108	  }, [data, isLoading, selectedPatient?.id]);
109	}
110	
111	/** A report is readable by the patient once the lab has finalised it. */
112	const READY_REPORT_STATUSES = [
113	  DiagnosticReportStatus.final,
114	  DiagnosticReportStatus.modified,
115	];
116	
117	export function usePatientDiagnosticReports() {
118	  const { selectedPatient } = usePatientContext();
119	  const { token, phoneNumber, headers } = useAuthHeaders();
120	
121	  const { data, isLoading } = useQuery({
122	    queryKey: ["portal-diagnostic-reports", phoneNumber, selectedPatient?.id],
123	    // Silent for the same reason as prescriptions — see above.
124	    queryFn: query(patientPortalApi.listDiagnosticReports, {
125	      headers,
126	      queryParams: { patient: selectedPatient?.id },
127	      silent: true,
128	    }),
129	    enabled: !!token && !!selectedPatient?.id,
130	  });
131	
132	  return useMemo(() => {
133	    const reports = (data?.results ?? [])
134	      .slice()
135	      .sort(
136	        (a, b) =>
137	          new Date(b.created_date).getTime() -
138	          new Date(a.created_date).getTime(),
139	      );
140	
141	    return {
142	      isLoading,
143	      reports,
144	      ready: reports.filter((r) => READY_REPORT_STATUSES.includes(r.status)),
145	      processing: reports.filter(
146	        (r) => !READY_REPORT_STATUSES.includes(r.status),
147	      ),
148	    };
149	  }, [data, isLoading, selectedPatient?.id]);
150	}
151	
152	export { READY_REPORT_STATUSES };
