(async () => {
  const raw = Object.keys(localStorage).filter(k => /token|patient/i.test(k)).map(k => [k, localStorage.getItem(k)?.slice(0, 120)]);
  return raw;
})()

(async () => {
  const tok = JSON.parse(localStorage.getItem('care_patient_token')).token;
  const base = 'http://127.0.0.1:9000';
  const r = await fetch(`${base}/api/v1/otp/appointments/`, { headers: { Authorization: `Bearer ${tok}` } });
  const j = await r.json();
  const first = j.results?.[0];
  return { status: r.status, count: j.results?.length, keys: first ? Object.keys(first) : null, sample: first ? JSON.stringify(first).slice(0, 900) : null };
})()
